sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var selectedTime = getDateFromFormat(
        newValue,
        g_user_date_time_format
    );

    if (selectedTime == 0) {
        g_form.showFieldMsg(
            'pickup_by',
            'Please enter a valid pickup date and time.',
            'error'
        );
        return;
    }

    var now = new Date().getTime();

    if (selectedTime < now) {
        g_form.clearValue('pickup_by');
        g_form.showFieldMsg(
            'pickup_by',
            'Pickup date and time must be now or in the future.',
            'error'
        );
    } else {
        g_form.hideFieldMsg('pickup_by', true);
    }
}
